-- Colours from the kirin colour scheme (generated by Quickshell with matugen).
-- Quickshell writes ~/.local/state/kirin/colors.lua and calls kirin_apply_colors()
-- on every change; on (re)load the last scheme is applied from that file.

local function rgba(hex, alpha)
	return "rgba(" .. hex .. (alpha or "ff") .. ")"
end

function kirin_apply_colors(c)
	if type(c) ~= "table" or not c.primary then return end

	hl.config({
		general = {
			col = {
				active_border = rgba(c.primary, "66"),
				inactive_border = rgba(c.outline_variant, "66"),
			},
		},
	})

	if hl.plugin.hyprbars then
		hl.config({
			plugin = {
				hyprbars = {
					bar_color = rgba(c.surface_container),
					col = { text = rgba(c.on_surface) },
				},
			},
		})
		-- The buttons keep their fixed colours (bars.lua).
		if hl.plugin.hyprbars.refresh then hl.plugin.hyprbars.refresh() end
	end
end

local state = os.getenv("XDG_STATE_HOME") or (os.getenv("HOME") .. "/.local/state")
local ok, colors = pcall(dofile, state .. "/kirin/colors.lua")
if ok then kirin_apply_colors(colors) end
